if(document.querySelector('#beta-dialog')){
const dialog=document.querySelector('#beta-dialog');let lastFocus;document.querySelectorAll('[data-beta]').forEach(b=>b.addEventListener('click',()=>{lastFocus=b;dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>lastFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
let draft='';document.querySelector('#beta-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);draft=`Hi RahaSec,\n\nI'd like to join the free KryonSec professional beta.\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nCompany / role: ${d.get('role')}\nEvaluation goal: ${d.get('goal')}\n\nPlease share the next steps and approved testing scope.\nThank you!`;document.querySelector('#email-fallback').hidden=false;window.location.href='mailto:hello@rahasec.com?subject='+encodeURIComponent('KryonSec free beta request')+'&body='+encodeURIComponent(draft)});document.querySelector('#copy-request').addEventListener('click',async e=>{try{await navigator.clipboard.writeText(draft);e.target.textContent='Copied ✓'}catch{const box=document.querySelector('#request-text');box.hidden=false;box.value=draft;box.select();e.target.textContent='Select and copy the draft below'}});

}
const log=document.querySelector('#terminal-log');const examples={help:'Available demo commands:\n  scan    Run a sample assessment\n  report  Read a sample finding\n  retest  Show sample verification\n  clear   Clear the terminal\n\nIllustrative syntax only. No real targets are scanned.',scan:'[scope]  owned-lab.example / isolated demo\n[check]  Authorization confirmed in sample scenario\n[run]    Illustrative assessment complete\n\n  01 sample finding ready for review\n  → Type report to take a closer look.\n\n[demo] No network request was made.',report:'FINDING DEMO-001 / SAMPLE DATA\n────────────────────────────────\nTitle     Missing Content-Security-Policy header\nEvidence  Header absent in the sample response\nNext step Review a policy appropriate to your app.\n          Test it in staging before enforcement.\n\nContext matters. This is not proof of exploitation.\n→ Type retest to see a sample follow-up.',retest:'[scope]  Same authorized sample application\n[check]  Content-Security-Policy header present\n[result] Sample condition changed after remediation\n\nA present header alone does not prove an effective policy.\nReview directives and application behavior.\n\n[demo] Verification scenario complete.'};
function run(raw){let cmd=raw.trim().toLowerCase();if(!cmd)return;if(cmd==='clear'){log.replaceChildren();return}const line=document.createElement('div');line.className='command-line';line.textContent='kryo@demo ~ $ '+raw;const out=document.createElement('div');out.className='output';out.textContent=examples[cmd]||'Unknown demo command. Type help for available commands.';log.append(line,out);log.scrollTop=log.scrollHeight;document.querySelectorAll('[data-command]').forEach(b=>b.classList.toggle('selected',b.dataset.command===cmd))}document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>run(b.dataset.command)));document.querySelector('#terminal-form').addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#command');run(input.value);input.value=''});
document.querySelector('#clear').addEventListener('click',()=>run('clear'));
document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{d.querySelector('summary span').textContent=d.open?'−':'+'}));

// The illustration is inline SVG so the eyes and arms can respond independently.
const creature=document.querySelector('.living-octopus');
const creatureStage=document.querySelector('.hero-art');
const speech=document.querySelector('.octo-speech');
const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
const motionControl=document.querySelector('#motion-control');
let paused=reduceMotion.matches, waveTimer, pointerFrame=0;
function setMotion(value){paused=value;document.body.classList.toggle('motion-paused',paused);motionControl.setAttribute('aria-pressed',String(paused));motionControl.textContent=paused?'Resume motion':'Pause motion';if(paused)document.querySelectorAll('.pupil').forEach(p=>p.style.transform='');}
setMotion(paused);reduceMotion.addEventListener('change',e=>setMotion(e.matches));
motionControl.addEventListener('click',()=>setMotion(!paused));
function greet(message='Hello, curious human.'){clearTimeout(waveTimer);speech.textContent=message;creatureStage.classList.remove('waving');void creatureStage.offsetWidth;creatureStage.classList.add('waving');waveTimer=setTimeout(()=>creatureStage.classList.remove('waving'),2600);}
document.querySelector('.say-hello').addEventListener('click',()=>greet());
window.addEventListener('pointermove',e=>{if(paused||reduceMotion.matches||e.pointerType==='touch'||pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;const matrix=creature.getScreenCTM();if(!matrix)return;const point=creature.createSVGPoint();point.x=e.clientX;point.y=e.clientY;const local=point.matrixTransform(matrix.inverse());document.querySelectorAll('.eye').forEach(eye=>{const x=Number(eye.dataset.x),y=Number(eye.dataset.y);const dx=local.x-x,dy=local.y-y,len=Math.hypot(dx,dy)||1;const amount=Math.min(len/22,8);eye.querySelector('.pupil').style.transform=`translate(${dx/len*amount}px,${dy/len*amount}px)`;});});},{passive:true});
document.documentElement.addEventListener('pointerleave',()=>document.querySelectorAll('.pupil').forEach(p=>p.style.transform=''));
const originalRun=run;
run=function(raw){originalRun(raw);const messages={scan:'Looking closer. In the demo, of course.',report:'Context matters. Keep asking why.',retest:'A second look is always useful.'};if(messages[raw.trim().toLowerCase()])greet(messages[raw.trim().toLowerCase()]);};
